   424→        function initGridLines() {
   425→            const tileWidth = parseFloat(document.getElementById('tileWidth').value);
   426→            const tileHeight = parseFloat(document.getElementById('tileHeight').value);
   427→            const cols = 10;
   428→            const rows = 4;
