   497→            // 渲染交叉锚点
   498→            if (showAnchors) {
   499→                for (let row = 0; row < hLines.length; row++) {
   500→                    for (let col = 0; col < vLines.length; col++) {
   501→                        const anchor = document.createElement('div');
