   540→
   541→        function startDrag(e) {
   542→            e.preventDefault();
   543→            const target = e.target.closest('.v-line, .h-line');
   544→            if (!target) return;
   545→
   546→            dragging = {
   547→                element: target,
   548→                type: target.dataset.type,
   549→                index: parseInt(target.dataset.index)
   550→            };
   551→
   552→            document.addEventListener('mousemove', onDrag);
   553→            document.addEventListener('mouseup', stopDrag);
   554→        }
   555→
   556→        function startDragAnchor(e) {
   557→            e.preventDefault();
   558→            dragging = {
   559→                element: e.target,
   560→                type: 'anchor',
   561→                row: parseInt(e.target.dataset.row),
   562→                col: parseInt(e.target.dataset.col)
   563→            };
   564→
   565→            document.addEventListener('mousemove', onDragAnchor);
   566→            document.addEventListener('mouseup', stopDrag);
   567→        }
   568→
   569→        function onDrag(e) {
   570→            if (!dragging) return;
   571→
   572→            const container = document.getElementById('imageContainer');
   573→            const rect = container.getBoundingClientRect();
   574→
   575→            if (dragging.type === 'v') {
   576→                const x = (e.clientX - rect.left) / imageScale;
   577→                vLines[dragging.index] = Math.max(0, Math.min(sourceImage.width, x));
   578→            } else if (dragging.type === 'h') {
   579→                const y = (e.clientY - rect.top) / imageScale;
   580→                hLines[dragging.index] = Math.max(0, Math.min(sourceImage.height, y));
   581→            }
   582→
   583→            renderGridLines();
   584→            updateCoordDisplay(e);
   585→        }
   586→
   587→        function onDragAnchor(e) {
   588→            if (!dragging || dragging.type !== 'anchor') return;
   589→
   590→            const container = document.getElementById('imageContainer');
   591→            const rect = container.getBoundingClientRect();
   592→
   593→            const x = (e.clientX - rect.left) / imageScale;
   594→            const y = (e.clientY - rect.top) / imageScale;
   595→
   596→            // 更新该锚点对应的垂直线和水平线
   597→            vLines[dragging.col] = Math.max(0, Math.min(sourceImage.width, x));
   598→            hLines[dragging.row] = Math.max(0, Math.min(sourceImage.height, y));
   599→
   600→            renderGridLines();
   601→            updateCoordDisplay(e);
   602→        }
   603→
   604→        function stopDrag() {
   605→            dragging = null;
   606→            document.removeEventListener('mousemove', onDrag);
   607→            document.removeEventListener('mousemove', onDragAnchor);
   608→            document.removeEventListener('mouseup', stopDrag);
   609→
   610→            // 更新参数显示
   611→            updateParamsFromLines();
   612→        }
   613→
   614→        function updateParamsFromLines() {
   615→            // 计算平均牌宽和牌高
   616→            let totalWidth = 0;
   617→            let totalHeight = 0;
   618→
   619→            for (let i = 0; i < vLines.length - 1; i++) {
   620→                totalWidth += vLines[i + 1] - vLines[i];
   621→            }
   622→
   623→            for (let i = 0; i < hLines.length - 1; i++) {
   624→                totalHeight += hLines[i + 1] - hLines[i];
   625→            }
   626→
   627→            const avgWidth = totalWidth / (vLines.length - 1);
   628→            const avgHeight = totalHeight / (hLines.length - 1);
   629→
   630→            document.getElementById('tileWidth').value = avgWidth.toFixed(2);
   631→            document.getElementById('tileHeight').value = avgHeight.toFixed(2);
   632→            document.getElementById('offsetX').value = vLines[0].toFixed(2);
   633→            document.getElementById('offsetY').value = hLines[0].toFixed(2);
   634→        }
   635→
   636→        function updateCoordDisplay(e) {
   637→            const display = document.getElementById('coordDisplay');
   638→            const container = document.getElementById('imageContainer');
   639→            const rect = container.getBoundingClientRect();
   640→
   641→            const x = (e.clientX - rect.left) / imageScale;
   642→            const y = (e.clientY - rect.top) / imageScale;
   643→
   644→            display.style.left = (e.clientX + 15) + 'px';
   645→            display.style.top = (e.clientY + 15) + 'px';
   646→            display.style.display = 'block';
   647→            display.textContent = `X: ${x.toFixed(1)}, Y: ${y.toFixed(1)}`;
   648→        }
   649→
   650→        document.addEventListener('mousemove', function(e) {
   651→            const container = document.getElementById('imageContainer');
   652→            if (container.style.display !== 'none') {
   653→                const rect = container.getBoundingClientRect();
   654→                if (e.clientX >= rect.left && e.clientX <= rect.right &&
   655→                    e.clientY >= rect.top && e.clientY <= rect.bottom) {
   656→                    updateCoordDisplay(e);
   657→                } else {
   658→                    document.getElementById('coordDisplay').style.display = 'none';
   659→                }
   660→            }
   661→        });
   662→
   663→        function updateGrid() {
   664→            const tileWidth = parseFloat(document.getElementById('tileWidth').value);
   665→            const tileHeight = parseFloat(document.getElementById('tileHeight').value);
   666→            const offsetX = parseFloat(document.getElementById('offsetX').value);
   667→            const offsetY = parseFloat(document.getElementById('offsetY').value);
   668→            const cols = 10;
   669→            const rows = 4;
   670→
   671→            vLines = [];
   672→            for (let i = 0; i <= cols; i++) {
   673→                vLines.push(offsetX + i * tileWidth);
   674→            }
   675→
   676→            hLines = [];
   677→            for (let i = 0; i <= rows; i++) {
   678→                hLines.push(offsetY + i * tileHeight);
   679→            }
   680→
   681→            renderGridLines();
   682→            updateStatus('<span class="success">网格已更新</span>');
   683→        }
   684→
   685→        function splitImage() {
   686→            if (!sourceImage) {
   687→                alert('请先加载图片！');
   688→                return;
   689→            }
   690→
   691→            splitCanvases = [];
   692→            const grid = document.getElementById('tilesGrid');
   693→            grid.innerHTML = '';
   694→
   695→            const rows = hLines.length - 1;
   696→            const cols = vLines.length - 1;
   697→
   698→            for (let row = 0; row < rows; row++) {
   699→                for (let col = 0; col < cols; col++) {
   700→                    const tileName = TILE_NAMES[row]?.[col];
   701→
   702→                    if (!tileName || tileName === 'back') continue;
   703→
   704→                    const x = vLines[col];
   705→                    const y = hLines[row];
   706→                    const width = vLines[col + 1] - x;
   707→                    const height = hLines[row + 1] - y;
   708→
   709→                    // 创建canvas
   710→                    const canvas = document.createElement('canvas');
   711→                    canvas.width = Math.round(width);
   712→                    canvas.height = Math.round(height);
   713→                    const ctx = canvas.getContext('2d');
   714→
   715→                    // 绘制裁剪的图片
   716→                    ctx.drawImage(
   717→                        sourceImage,
   718→                        x, y, width, height,
   719→                        0, 0, width, height
   720→                    );
   721→
   722→                    splitCanvases.push({ name: tileName, canvas: canvas, row, col, x, y, width, height });
   723→
   724→                    // 显示预览
   725→                    const item = document.createElement('div');
   726→                    item.className = 'tile-item';
   727→                    item.innerHTML = `
   728→                        <img src="${canvas.toDataURL('image/png')}">
   729→                        <div class="name">${tileName}</div>
   730→                    `;
   731→                    grid.appendChild(item);
   732→                }
   733→            }
   734→
   735→            updateStatus(`<span class="success">分割完成！共 ${splitCanvases.length} 张牌</span>`);
   736→        }
   737→
   738→        function downloadAll() {
   739→            if (splitCanvases.length === 0) {
   740→                alert('请先分割图片！');
   741→                return;
   742→            }
   743→
   744→            splitCanvases.forEach((item, index) => {
   745→                setTimeout(() => {
   746→                    const link = document.createElement('a');
   747→                    link.download = `${item.name}.png`;
   748→                    link.href = item.canvas.toDataURL('image/png');
   749→                    link.click();
   750→                }, index * 100);
   751→            });
   752→
   753→            updateStatus(`<span class="success">正在下载 ${splitCanvases.length} 张图片...</span>`);
   754→        }
   755→
   756→        function resetParams() {
   757→            document.getElementById('tileWidth').value = 61.7;
   758→            document.getElementById('tileHeight').value = 93.25;
   759→            document.getElementById('offsetX').value = 0;
   760→            document.getElementById('offsetY').value = 0;
   761→            updateGrid();
   762→        }
   763→
   764→        function updateStatus(msg) {
   765→            document.getElementById('statusText').innerHTML = msg;
   766→        }
   767→
   768→        // 监听复选框变化
   769→        document.getElementById('showGrid').addEventListener('change', renderGridLines);
   770→        document.getElementById('showAnchors').addEventListener('change', renderGridLines);
   771→        document.getElementById('showLabels').addEventListener('change', renderGridLines);
   772→
   773→        // 页面加载时自动加载默认图片
   774→        window.onload = function() {
   775→            const img = new Image();
   776→            img.crossOrigin = 'anonymous';
   777→            img.onload = function() {
   778→                sourceImage = img;
   779→                displayImage();
   780→            };
   781→            img.onerror = function() {
   782→                updateStatus('请手动选择麻将大图文件');
   783→            };
   784→            img.src = '麻将大图.jpg';
   785→        };
   786→    </script>
